import pdfplumber
import pandas as pd
import json

def clean_pdf_val(val, field):
    if val is None:
        return None
    if field in ['Salary', 'Years']:
        try:
            return int(str(val).replace(',', ''))
        except ValueError:
            return val
    if field == 'Score':
        try:
            return float(val)
        except ValueError:
            return val
    return str(val)

def compare():
    # Extract data from PDF
    pdf_employees = {}
    with pdfplumber.open("employees_backup.pdf") as pdf:
        headers = None
        for page in pdf.pages:
            tables = page.extract_tables()
            for table in tables:
                if not table:
                    continue

                # Assume first table first row of first page is header
                if headers is None:
                    headers = table[0]
                    rows = table[1:]
                else:
                    # Check if first row is header (contains 'ID')
                    if 'ID' in table[0]:
                        rows = table[1:]
                    else:
                        rows = table

                for row in rows:
                    if not row or len(row) < len(headers):
                        continue
                    emp_id = row[0]
                    if not emp_id.startswith('EMP'):
                        continue

                    emp_data = {}
                    for i, header in enumerate(headers):
                        emp_data[header] = clean_pdf_val(row[i], header)
                    pdf_employees[emp_id] = emp_data

    # Read data from Excel
    df_excel = pd.read_excel("employees_current.xlsx")
    excel_employees = {}
    for _, row in df_excel.iterrows():
        emp_id = str(row['ID'])
        excel_employees[emp_id] = row.to_dict()

    # Compare
    deleted_employees = []
    modified_employees = []

    # Sort IDs for consistency
    all_pdf_ids = sorted(pdf_employees.keys())

    for emp_id in all_pdf_ids:
        if emp_id not in excel_employees:
            deleted_employees.append(emp_id)
        else:
            old_data = pdf_employees[emp_id]
            new_data = excel_employees[emp_id]

            # Fields to compare (all except ID)
            fields = [f for f in old_data.keys() if f != 'ID']
            for field in fields:
                old_val = old_data[field]
                new_val = new_data[field]

                # Data cleaning for Excel data if needed (e.g. Score might be float, Salary int)
                # pandas usually handles this well, but let's be sure

                # Special handling for numeric comparison to avoid float precision issues if any
                is_different = False
                if isinstance(old_val, (int, float)) and isinstance(new_val, (int, float)):
                    if abs(old_val - new_val) > 1e-9:
                        is_different = True
                else:
                    if str(old_val) != str(new_val):
                        is_different = True

                if is_different:
                    modified_employees.append({
                        "id": emp_id,
                        "field": field,
                        "old_value": old_val,
                        "new_value": new_val
                    })

    # Note: modified_employees should also be sorted by ID and then field?
    # Prompt says: "Sort deleted_employees and modified_employees by ID for consistency"
    modified_employees.sort(key=lambda x: (x['id'], x['field']))
    deleted_employees.sort()

    report = {
        "deleted_employees": deleted_employees,
        "modified_employees": modified_employees
    }

    with open("diff_report.json", "w") as f:
        json.dump(report, f, indent=2)

if __name__ == "__main__":
    compare()

